import '@servicenow/sdk/global'
import { IntegerColumn } from '@servicenow/sdk/core'
import { Flow, trigger, wfa, action } from '@servicenow/sdk/automation'

// =============================================================================
// Test Flow: Simple ForEach with Log Action
// =============================================================================
export const flowForEachSimple = Flow(
    {
        $id: Now.ID['flow-foreach-simple-v3'],
        name: 'ForEach Simple V3',
        description: 'ForEach bi-directional test - v3',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            counter: IntegerColumn({
                label: 'Counter',
                mandatory: false,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['foreach-simple-trigger-v3'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // Simple ForEach with log action
        wfa.flowLogic.forEach(
            wfa.dataPill(params.trigger.current.watch_list, 'array.string'),
            {
                $id: Now.ID['foreach-simple-loop-v3'],
                annotation: 'Process each user in watch list',
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['foreach-simple-log-v3'],
                    },
                    {
                        log_level: 'info',
                        log_message: 'Processing user from watch list',
                    }
                )
            }
        )
    }
)
